source.exploreUrl:
@js:
sort = [];
push = (title, url, type1, type2) => sort.push({
    title: title,
    url: url,
    style: {
        layout_flexGrow: type1,
        layout_flexBasisPercent: type2
    }
});

const requestTypes = [
    { sourceType: "男频", channel: 1 },
    { sourceType: "女频", channel: 2 }
];
java.longToast("请稍等，发现列表正在热更新！");
requestTypes.forEach(type => {
    // 推送男频/女频分类标题
    push(type.sourceType, "", 1, 1);
    const apiUrl = `http://api.daislou.com/novel/category?channel=${type.channel}`;
    const response = java.ajax(apiUrl);
    const result = JSON.parse(response);

    // 校验响应格式，提取categories数据
    if (result.msg === "success" && result.data?.categories && Array.isArray(result.data.categories)) {
        result.data.categories.forEach(category => {
            const categoryUrl = `http://api.daislou.com/novel?sort=1&page={{page}}&categoryId=${category.categoryId}`;
            // 推送分类名称和对应链接
            push(category.categoryName, categoryUrl, 1, 0.2);
        });
    }
});

JSON.stringify(sort);

