        } catch (e) { err = String(e); }
    }
}
var out = lkHtml(d);
if (d.locked == 1) out = (out ? out + '\n' : '') + lkLockTip(d, !!key, coinOn, err);
else if (!out) out = '⚠️ 本章暂无内容';
