@js:
function login() {
    var info = source.getLoginInfoMap() || {};
    var u = info.get ? info.get('账号') : info['账号'];
    var p = info.get ? info.get('密码') : info['密码'];
    if (!u || !p) throw new Error('请先填写账号和密码');
    var r = JSON.parse(java.ajax(lkUrl('/bff/auth-password-login-v1', {username: String(u), password: String(p)})));
    if (r.code == 0 && r.data && r.data.auth && r.data.auth.security_key) {
        source.put('lk_key', String(r.data.auth.security_key));
        java.toast('✅ 登录成功：' + ((r.data.user && r.data.user.nickname) || r.data.auth.uid));
        return;
    }
    throw new Error(r.code == 2 ? '账号或密码错误' : '登录失败 code:' + r.code);
}

function lkStatus() {
    var key = lkKey(source);
    if (!key) { java.toast('⚪ 未登录'); return; }
    var r = JSON.parse(java.ajax(lkUrl('/bff/auth-session-v1', {}, key)));
    if (r.code == 0 && r.data && r.data.logged_in == 1) {
        var u = r.data.user || {};
        java.toast('✅ 已登录：' + (u.nickname || u.uid) + (u.level ? '（' + u.level.name + '）' : ''));
    } else {
        java.toast('⚠️ 登录已失效，请重新登录');
    }
}

function lkLogout() {
    source.put('lk_key', '');
    java.toast('🚪 已退出登录');
}

function lkToggleCoin() {
    var on = !lkCoinOn(source);
    source.put('lk_coin', on ? '1' : '');
    java.toast(on ? '💰 花费轻币：已开启（打开付费章节时自动解锁）' : '💰 花费轻币：已关闭');
}

function lkToggleZh() {
    var on = !lkZhOn(source);
    source.put('lk_zh', on ? '1' : '');
    java.toast(on ? '🈶 繁转简：已开启（刷新目录后生效）' : '🈶 繁转简：已关闭');
}

