var key = lkKey(source);
var zh = lkZhOn(source);
var d = JSON.parse(result).data || {};
var vols = d.volumes || [];
if (vols.length < (d.volume_count || 0)) {
    vols = [];
    for (var p = 1, pages = 1; p <= pages; p++) {
        var r = JSON.parse(java.ajax(lkUrl('/new-content-read/get-book-volumes', {book_id: d.book_id, page: p, page_size: 50}, key))).data || {};
        pages = (r.pagination && r.pagination.page_count) || 1;
        vols = vols.concat(r.list || []);
    }
}

var BATCH = 4;
var pages = {};
var queue = vols.map(function (v, i) { return [i, 1]; });
while (queue.length) {
    var batch = queue.splice(0, BATCH);
    var res = java.ajaxAll(batch.map(function (t) {
        return lkUrl('/new-content-read/get-volume-chapters', {volume_id: vols[t[0]].volume_id, page: t[1], page_size: 50}, key);
    }));
    batch.forEach(function (t, j) {
        var body = String(res[j].body());
        var r;
        try { r = JSON.parse(body).data || {}; } catch (e) { throw new Error('目录获取失败：' + body.slice(0, 60)); }
        pages[t[0] + ':' + t[1]] = r.list || [];
        var count = (r.pagination && r.pagination.page_count) || 1;
        if (t[1] == 1) for (var n = 2; n <= count; n++) queue.push([t[0], n]);
    });
}

var out = [];
vols.forEach(function (v, i) {
    var vt = String(v.title || '');
    out.push(JSON.stringify({title: zh ? String(java.t2s(vt)) : vt, url: '', volume: 'true', vip: '', time: ''}));
    for (var n = 1; pages[i + ':' + n]; n++) {
        pages[i + ':' + n].forEach(function (c) {
            var t = String(c.title || '');
            if (zh) t = String(java.t2s(t));
            var lock = c.locked == 1;
            out.push(JSON.stringify({
                title: (lock ? '🔒 ' : '') + t,
                url: lkChapter(c.chapter_id),
                volume: '',
                vip: lock ? 'true' : '',
                time: String(c.published_at || '')
            }));
        });
    }
});
out;

source.exploreUrl:
@js:
var cfg = {};
try { cfg = JSON.parse(String(source.getVariable() || '{}')) || {}; } catch (e) {}

var tax = cfg.fast && cfg.tax;
if (!tax) {
    tax = null;
    try {
        var tab = (JSON.parse(java.ajax(lkTaxonomy())).data.tabs || [])[0] || {};
        tax = {
            ch: (tab.channels || []).map(function (c) {
                return [String(c.label), String((c.filter_payload && c.filter_payload.work_type) || c.code)];
            }),
            groups: (tab.groups || []).filter(function (g) {
                return String(g.title).indexOf('热门') < 0;
            }).map(function (g) {
                var items = [];
                (g.sections || []).forEach(function (sec) {
                    (sec.tag_items || []).forEach(function (t) {
                        items.push([String(t.title), t.filter_payload || {q: '', primary_tag: String(t.title)}]);
                    });
                });
                return [String(g.title), items];
            }).filter(function (g) { return g[1].length; })
        };
        if (tax.groups.length) cfg.tax = tax;
    } catch (e) {}
    tax = tax || {ch: [], groups: []};
}
delete cfg.fast;
source.setVariable(JSON.stringify(cfg));

var CH = [['全部', '', 'all']].concat(tax.ch.map(function (c) { return [c[0], c[1], c[1]]; }));
var ch = CH.filter(function (c) { return c[1] == cfg.ch; })[0] || CH[0];
var open = cfg.open || {};
var sort = cfg.sort || 'relevance', status = cfg.st || 'all';

var SORT = [['默认排序', 'relevance'], ['最新', 'new'], ['评分', 'score'], ['字数', 'words']];
var STATUS = [['全部状态', 'all'], ['完结', 'completed'], ['连载', 'serializing']];
function label(opts, v) { return (opts.filter(function (o) { return o[1] == v; })[0] || opts[0])[0]; }

var LAYOUT = {gap: 0.042, pad: 0.068, ch: 0.0368, shortMax: 3.3};

function textWidth(t) {
    var w = 0;
    for (var i = 0; i < t.length; i++) {
        var c = t.charCodeAt(i);
        if (c == 32) w += 0.32;
        else if (c < 128) w += 0.65;
        else if (c == 0xB7) w += 0.5;
        else if (c == 0x25CF) w += 0.9;
        else w += 1;
    }
    return w;
}

var s = [];

function pack(items, cols) {
    cols = cols || 4;
    var g = LAYOUT.gap, cell = (1 - g * (cols - 1)) / cols;
    var fit = (cell - LAYOUT.pad) / LAYOUT.ch;
    var queue = items.map(function (it) {
        return {it: it, span: Math.min(cols, Math.ceil(textWidth(it.title) / fit) || 1)};
    });
    while (queue.length) {
        var row = [], left = cols;
        while (queue.length && left > 0) {
            var k = 0;
            while (k < queue.length && queue[k].span > left) k++;
            if (k == queue.length) break;
            var x = queue.splice(k, 1)[0];
            row.push(x); left -= x.span;
        }
        for (; left > 0; left--) row.push({it: {title: '　', url: ''}, span: 1});
        row.forEach(function (x, i) {
            var st = {layout_flexGrow: x.span, layout_flexBasisPercent: Math.round((x.span / (cols + 1) + (x.span - 1) * g) * 1e4) / 1e4};
            if (i == 0) st.layout_wrapBefore = true;
            x.it.style = st;
            s.push(x.it);
        });
    }
}

function action(js) {
    return "(function(){var c={};try{c=JSON.parse(String(source.getVariable()||'{}'))||{};}catch(e){}"
        + js + "c.fast=1;source.setVariable(JSON.stringify(c));java.refreshExplore();})()";
}
function button(title, js) {
    return {title: title, type: 'button', action: action(js)};
}
function bar(title, js) {
    var b = button(title, js);
    b.style = {layout_flexGrow: 1, layout_flexBasisPercent: 1, layout_wrapBefore: true};
    s.push(b);
}
function optionRow(key, opts, cur) {
    pack(opts.map(function (o) {
        return button((o[1] == cur ? '● ' : '') + o[0], 'c[' + JSON.stringify(key) + ']=' + JSON.stringify(o[1]) + ';');
    }), 3);
}

function listUrl(payload) {
    return "{{lkList('" + encodeURIComponent(JSON.stringify(payload)) + "',page,'" + ch[1] + "','" + sort + "','" + status + "')}}";
}

function group(name, defOpen, count, build) {
    var isOpen = name in open ? !!open[name] : defOpen;
    bar((isOpen ? '▾ ' : '▸ ') + name + '（' + count + '）',
        'var o=c.open||{};o[' + JSON.stringify(name) + ']=' + (isOpen ? 0 : 1) + ';c.open=o;');
    if (isOpen) build();
}

pack(CH.map(function (c) {
    return button((c[1] == ch[1] ? '● ' : '') + c[0], 'c.ch=' + JSON.stringify(c[1]) + ';');
}), 3);

bar('⚙ 筛选：' + label(SORT, sort) + ' · ' + label(STATUS, status) + (cfg.filt ? '　▾' : '　▸'), 'c.filt=!c.filt;');
if (cfg.filt) {
    optionRow('sort', SORT, sort);
    optionRow('st', STATUS, status);
}

group('书库', true, 3, function () {
    pack([
        {title: '最近更新', url: listUrl({q: '最近更新'})},
        {title: '日榜', url: "{{lkRank('daily_" + ch[2] + "',page)}}"},
        {title: '周榜', url: "{{lkRank('weekly_" + ch[2] + "',page)}}"}
    ], 3);
});

if (!tax.groups.length) s.push({title: '⚠ 分类加载失败', url: '', style: {layout_flexGrow: 1, layout_flexBasisPercent: 1, layout_wrapBefore: true}});
tax.groups.forEach(function (g, gi) {
    group(g[0], gi == 0, g[1].length, function () {
        var short = [], long = [];
        g[1].forEach(function (t) {
            var it = {title: t[0], url: listUrl(t[1])};
            (textWidth(t[0]) > LAYOUT.shortMax ? long : short).push(it);
        });
        pack(short, 4);
        pack(long, 3);
    });
});

JSON.stringify(s);

