@js:
function createRequest(id, reqPath) {
  let p = reqPath || "getthirdinfobysecondid";
  let url = `https://android.goreadnovels.com/categorysetajax/${p}.do`;
  let body = `id=${id}&page={{page}}&pagesize=10`;
  return `${url},{"body":"${body}","method":"POST"}`;
}

let ids = [12, 56, 57, 59, 110];
let ah = java.ajaxAll(ids.map(id => createRequest(id)));

let list = [];

function push_list(title, url, flexBasisPercent) {
  list.push({
    title,
    url,
    style: {
      layout_flexGrow: "1",
      layout_flexBasisPercent: flexBasisPercent
    }
  });
}

function cy(res, flexBasisPercent) {
  if (!res) return;
  try {
    let bodyText = typeof res.body === 'function' ? res.body() : res;
    if (!bodyText) return;
    let json = JSON.parse(bodyText);
    if (json && json.data && Array.isArray(json.data)) {
      json.data.forEach(({ id, title }) => {
        push_list(title, createRequest(id, "getcategorydetailinfo"), flexBasisPercent);
      });
    }
  } catch (e) {}
}

push_list("▱▱▱▱男生▱▱▱▱", null, "1");
if (ah && ah[0]) cy(ah[0], "0.25");

push_list("▱▱▱▱女生▱▱▱▱", null, "1");
if (ah && ah[1]) cy(ah[1], "0.25");

push_list("▱▱▱▱短篇▱▱▱▱", createRequest(57, "getcategorydetailinfo"), "1");
push_list("▱▱▱▱二次元▱▱▱▱", createRequest(59, "getcategorydetailinfo"), "1");
push_list("▱▱▱▱出版▱▱▱▱", createRequest(110, "getcategorydetailinfo"), "1");

JSON.stringify(list);

